import { RotateCw, TriangleAlert } from 'lucide-react'

import { Button } from '#/components/ui/button'
import { cn } from '#/lib/utils.ts'

interface ErrorStateProps {
  title: string
  description: string
  onRetry?: () => void
  isRetrying?: boolean
  /** `panel` fills an empty table body; `banner` sits above stale rows */
  variant?: 'panel' | 'banner'
}

export function ErrorState({
  title,
  description,
  onRetry,
  isRetrying = false,
  variant = 'panel',
}: ErrorStateProps) {
  const retry = onRetry && (
    <Button variant="outline" size="sm" onClick={onRetry} disabled={isRetrying}>
      <RotateCw className={cn(isRetrying && 'animate-spin')} />
      {isRetrying ? 'Retrying...' : 'Try again'}
    </Button>
  )

  if (variant === 'banner') {
    return (
      <div
        role="alert"
        className="flex flex-wrap items-center gap-3 rounded-md border border-destructive/30 bg-destructive/5 px-4 py-3"
      >
        <TriangleAlert className="size-4 shrink-0 text-destructive" />
        <div className="min-w-0 flex-1 text-sm">
          <p className="font-medium">{title}</p>
          <p className="text-muted-foreground">{description}</p>
        </div>
        {retry}
      </div>
    )
  }

  return (
    <div
      role="alert"
      className="flex flex-col items-center justify-center gap-3 px-6 py-14 text-center"
    >
      <div className="flex size-11 items-center justify-center rounded-full bg-destructive/10 text-destructive">
        <TriangleAlert className="size-5" />
      </div>
      <div className="space-y-1">
        <p className="text-sm font-medium">{title}</p>
        <p className="max-w-sm text-sm text-balance text-muted-foreground">
          {description}
        </p>
      </div>
      {retry}
    </div>
  )
}

'use client'

import {
  flexRender,
  getCoreRowModel,
  useReactTable,
} from '@tanstack/react-table'
import type { ColumnDef } from '@tanstack/react-table'

import { Badge } from '#/components/ui/badge'
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '#/components/ui/table'
import { ErrorState } from './error-state'
import type { Invoice } from './data'

export const columns: ColumnDef<Invoice>[] = [
  {
    accessorKey: 'customer',
    header: 'Customer',
    cell: ({ row }) => (
      <div className="flex flex-col">
        <span className="font-medium">{row.original.customer}</span>
        <span className="text-xs text-muted-foreground">
          {row.original.email}
        </span>
      </div>
    ),
  },
  {
    accessorKey: 'status',
    header: 'Status',
    cell: ({ row }) => (
      <Badge
        variant={
          row.original.status === 'Overdue' ? 'destructive' : 'secondary'
        }
      >
        {row.original.status}
      </Badge>
    ),
  },
  {
    accessorKey: 'amount',
    header: () => <div className="text-right">Amount</div>,
    cell: ({ row }) => (
      <div className="text-right tabular-nums">
        {row.original.amount.toLocaleString('en-US', {
          style: 'currency',
          currency: 'USD',
        })}
      </div>
    ),
  },
  { accessorKey: 'dueDate', header: 'Due' },
]

interface DataTableProps {
  data: Invoice[]
  error?: Error | null
  onRetry?: () => void
  isRetrying?: boolean
}

export function DataTable({
  data,
  error = null,
  onRetry,
  isRetrying = false,
}: DataTableProps) {
  const table = useReactTable({
    data,
    columns,
    getCoreRowModel: getCoreRowModel(),
  })

  const rows = table.getRowModel().rows
  // With rows already on screen, keep them and show the error as a banner;
  // with nothing to show, the error takes the place of the body.
  const hasStaleData = rows.length > 0

  return (
    <div className="space-y-3">
      {error && hasStaleData && (
        <ErrorState
          variant="banner"
          title="Couldn't refresh invoices"
          description={`${error.message}. Showing the last loaded data.`}
          onRetry={onRetry}
          isRetrying={isRetrying}
        />
      )}
      <div className="overflow-hidden rounded-md border">
        <Table>
          <TableHeader>
            {table.getHeaderGroups().map((headerGroup) => (
              <TableRow key={headerGroup.id}>
                {headerGroup.headers.map((header) => (
                  <TableHead key={header.id}>
                    {header.isPlaceholder
                      ? null
                      : flexRender(
                          header.column.columnDef.header,
                          header.getContext(),
                        )}
                  </TableHead>
                ))}
              </TableRow>
            ))}
          </TableHeader>
          <TableBody>
            {rows.length ? (
              rows.map((row) => (
                <TableRow key={row.id}>
                  {row.getVisibleCells().map((cell) => (
                    <TableCell key={cell.id}>
                      {flexRender(
                        cell.column.columnDef.cell,
                        cell.getContext(),
                      )}
                    </TableCell>
                  ))}
                </TableRow>
              ))
            ) : (
              <TableRow className="hover:bg-transparent">
                <TableCell colSpan={columns.length} className="p-0">
                  {error ? (
                    <ErrorState
                      title="Something went wrong"
                      description={`${error.message}. Check your connection and try again.`}
                      onRetry={onRetry}
                      isRetrying={isRetrying}
                    />
                  ) : null}
                </TableCell>
              </TableRow>
            )}
          </TableBody>
        </Table>
      </div>
    </div>
  )
}

import { useCallback, useEffect, useRef, useState } from 'react'

import { Button } from '#/components/ui/button'
import { DataTable } from './data-table'
import { invoices } from './data'
import type { Invoice } from './data'

export function ErrorStateTableDemo() {
  const [data, setData] = useState<Invoice[]>([])
  const [error, setError] = useState<Error | null>(
    new Error('Request failed with status 503'),
  )
  const [isRetrying, setIsRetrying] = useState(false)
  const timer = useRef<ReturnType<typeof setTimeout>>(undefined)

  useEffect(() => () => clearTimeout(timer.current), [])

  // Stand-in for refetching: succeeds after a short delay
  const retry = useCallback(() => {
    setIsRetrying(true)
    timer.current = setTimeout(() => {
      setData(invoices)
      setError(null)
      setIsRetrying(false)
    }, 1200)
  }, [])

  const failWith = (rows: Invoice[]) => {
    clearTimeout(timer.current)
    setIsRetrying(false)
    setData(rows)
    setError(new Error('Request failed with status 503'))
  }

  return (
    <div className="space-y-3">
      <div className="flex flex-wrap gap-2">
        <Button variant="outline" size="sm" onClick={() => failWith([])}>
          Fail with no data
        </Button>
        <Button variant="outline" size="sm" onClick={() => failWith(invoices)}>
          Fail with stale data
        </Button>
      </div>
      <DataTable
        data={data}
        error={error}
        onRetry={retry}
        isRetrying={isRetrying}
      />
    </div>
  )
}
